	var folderBounds *swt.Rectangle = this.ctabFolder.GetBounds()
	junit.AssertTrue(topRightBounds.Y >= 0, fmt.Sprintf("topRight must not be clipped at the top. topRight.y=%d", topRightBounds.Y))
